import{_ as s,o as i,c as a,ag as n}from"./chunks/framework.CHTsTv39.js";const p=JSON.parse('{"title":"MAVLink Message Signing","description":"","frontmatter":{"github_branch":"main"},"headers":[],"relativePath":"en/cpp/guide/message_signing.md","filePath":"en/cpp/guide/message_signing.md"}'),t={name:"en/cpp/guide/message_signing.md"};function o(l,e,d,h,g,c){return i(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="mavlink-message-signing" tabindex="-1">MAVLink Message Signing <a class="header-anchor" href="#mavlink-message-signing" aria-label="Permalink to &quot;MAVLink Message Signing&quot;">​</a></h1><p>MAVSDK can sign the MAVLink 2 messages it sends and check the signature of the ones it receives, as described in <a href="https://mavlink.io/en/guide/message_signing.html" target="_blank" rel="noreferrer">MAVLink Message Signing</a>. This makes sure that only systems with the shared secret key can command a vehicle or feed data to the application.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Signing authenticates messages, it does not encrypt them: anyone listening can still read them.</p></div><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p>Signing is disabled by default. It is enabled with a 32 byte secret key, which is shared by all systems on the network:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::array</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;uint8_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Mavsdk</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::SIGNING_KEY_LENGTH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> secret_key </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> load_key_from_somewhere</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mavsdk.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">enable_signing</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(secret_key);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ...</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mavsdk.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">disable_signing</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>Once enabled, for all connections:</p><ul><li><p>All outgoing MAVLink 2 messages are signed. MAVLink 1 messages can&#39;t be signed and are sent as they are.</p></li><li><p>Incoming messages without a valid signature are dropped, including signed messages that are replayed. This includes <code>HEARTBEAT</code>, so a system that doesn&#39;t sign with the same key is not discovered at all. It also includes <code>RADIO_STATUS</code> injected by radios that can&#39;t sign, such as SiK radios.</p></li><li><p>Dropped messages are not forwarded either, so with <a href="./connections.html#forwarding-mavlink-between-connections">message forwarding</a> MAVSDK only passes on correctly signed messages.</p></li><li><p>Dropped messages are logged as a warning with the reason (e.g. bad signature, not signed, timestamp too old), at most once every 5 seconds. Only the unsigned <code>RADIO_STATUS</code> of radios is logged at debug level, as it&#39;s expected.</p></li></ul><p>Disabling signing again sends messages unsigned and accepts all incoming messages.</p><p>MAVSDK does not store the key, so the application has to enable signing again on each start.</p><h2 id="timestamps-and-replay-protection" tabindex="-1">Timestamps and replay protection <a class="header-anchor" href="#timestamps-and-replay-protection" aria-label="Permalink to &quot;Timestamps and replay protection&quot;">​</a></h2><p>Each signed message carries a timestamp, and MAVSDK only accepts messages from a system whose timestamps keep increasing. MAVSDK signs with the current system time, so the computer it runs on needs a correct clock.</p><p>A system that MAVSDK hasn&#39;t heard from yet is accepted if its timestamp is less than one minute behind MAVSDK&#39;s. If the vehicle&#39;s signing timestamp is further behind, MAVSDK drops its messages at first, and logs that the timestamp is behind. It sends the vehicle heartbeats meanwhile: a vehicle usually moves its timestamp forward to the newest one it receives, after which it is accepted. Such a message might also be a replay, so over UDP the sender is not added as a destination until its messages are accepted: it only gets a heartbeat back, at most once a second. With PX4 this takes about a second.</p><p>What MAVSDK has seen is kept in memory only. After a restart, after <code>disable_signing()</code>, or after enabling signing with a different key, a message recorded within the last minute could be replayed once. Calling <code>enable_signing()</code> again with the same key while signing is enabled keeps what it has seen.</p><h2 id="setting-up-the-key-on-the-vehicle" tabindex="-1">Setting up the key on the vehicle <a class="header-anchor" href="#setting-up-the-key-on-the-vehicle" aria-label="Permalink to &quot;Setting up the key on the vehicle&quot;">​</a></h2><p>The vehicle has to know the same key. How it gets there is up to the application: it can be sent with a <a href="https://mavlink.io/en/messages/common.html#SETUP_SIGNING" target="_blank" rel="noreferrer">SETUP_SIGNING</a> message, e.g. using <a href="./mavlink_direct.html">MavlinkDirect</a>, over a secure link such as USB, before enabling signing in MAVSDK. PX4 stores the key and signs from then on, starting at the <code>initial_timestamp</code> of <code>SETUP_SIGNING</code>, so set that to the current time. A <code>SETUP_SIGNING</code> with an all-zero key disables signing on PX4 again.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>PX4 accepts some messages unsigned even when signing: <code>HEARTBEAT</code>, <code>RADIO_STATUS</code>, <code>ADSB_VEHICLE</code> and <code>COLLISION</code>. MAVSDK does not make these exceptions.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Once the vehicle signs, it drops unsigned commands. If the key is lost, it has to be reset on the vehicle directly.</p></div><h2 id="language-bindings" tabindex="-1">Language bindings <a class="header-anchor" href="#language-bindings" aria-label="Permalink to &quot;Language bindings&quot;">​</a></h2><p>The same functions are available in the native bindings:</p><ul><li>C: <code>mavsdk_enable_signing()</code>, <code>mavsdk_disable_signing()</code>, <code>mavsdk_is_signing_enabled()</code></li><li>Python: <code>Mavsdk.enable_signing(secret_key: bytes)</code>, <code>disable_signing()</code>, <code>is_signing_enabled()</code></li><li>Kotlin: <code>Mavsdk.enableSigning(secretKey: ByteArray)</code>, <code>disableSigning()</code>, <code>isSigningEnabled()</code></li></ul><p>Signing is not available through <em>mavsdk_server</em>.</p>`,22)])])}const m=s(t,[["render",o]]);export{p as __pageData,m as default};
